-- Candidate operations require an active candidate or platform owner role.
alter policy profile_self_read on public.pilot_profiles using(user_id=(select auth.uid()) and exists(select 1 from public.pilot_memberships m where m.user_id=(select auth.uid()) and m.status='active' and m.role in ('learner','pilot_owner')));
alter policy profile_self_update on public.pilot_profiles using(user_id=(select auth.uid()) and exists(select 1 from public.pilot_memberships m where m.user_id=(select auth.uid()) and m.status='active' and m.role in ('learner','pilot_owner'))) with check(user_id=(select auth.uid()) and exists(select 1 from public.pilot_memberships m where m.user_id=(select auth.uid()) and m.status='active' and m.role in ('learner','pilot_owner')));
alter policy goal_self_read on public.pilot_goals using(user_id=(select auth.uid()) and exists(select 1 from public.pilot_memberships m where m.user_id=(select auth.uid()) and m.cohort_id=pilot_goals.cohort_id and m.status='active' and m.role in ('learner','pilot_owner')));
alter policy goal_self_insert on public.pilot_goals with check(user_id=(select auth.uid()) and exists(select 1 from public.pilot_memberships m where m.user_id=(select auth.uid()) and m.cohort_id=pilot_goals.cohort_id and m.status='active' and m.role in ('learner','pilot_owner')));
alter policy goal_self_update on public.pilot_goals using(user_id=(select auth.uid()) and exists(select 1 from public.pilot_memberships m where m.user_id=(select auth.uid()) and m.cohort_id=pilot_goals.cohort_id and m.status='active' and m.role in ('learner','pilot_owner'))) with check(user_id=(select auth.uid()) and exists(select 1 from public.pilot_memberships m where m.user_id=(select auth.uid()) and m.cohort_id=pilot_goals.cohort_id and m.status='active' and m.role in ('learner','pilot_owner')));
